def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if not isinstance(nanoseconds, (int, long)):
        raise ValueError("nanoseconds must be an integer")

    if tz is not None and not isinstance(tz, timezone):
        raise ValueError("tz must be a timezone object")

    seconds = nanoseconds // 1e9
    microseconds = (nanoseconds % 1e9) // 1e3

    if tz is not None:
        return datetime(1970, 1, 1) + timedelta(seconds=seconds, microseconds=microseconds) + tz
    else:
        return datetime(1970, 1, 1) + timedelta(seconds=seconds, microseconds=microseconds)

from datetime import datetime, timedelta

class Time:
    def __init__(self, nanoseconds, tz=None):
        self.nanoseconds = nanoseconds
        self.tz = tz

    @staticmethod
    def hydrate(nanoseconds, tz=None):
        if tz is not None:
            tz_offset = timedelta(hours=tz)
            timestamp = datetime.fromtimestamp(nanoseconds / 1e9, tz=tz_offset)
        else:
            timestamp = datetime.fromtimestamp(nanoseconds / 1e9)

        return Time(nanoseconds, tz)

class LocalTime:
    def __init__(self, nanoseconds, tz=None):
        self.nanoseconds = nanoseconds
        self.tz = tz

    @staticmethod
    def hydrate(nanoseconds, tz=None):
        if tz is not None:
            tz_offset = timedelta(hours=tz)
            timestamp = datetime.now(tz=tz_offset)
        else:
            timestamp = datetime.now()

        return LocalTime(int(timestamp.timestamp() * 1e9), tz)

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timedelta, tzinfo
    import pytz

    try:
        # Calculate seconds and nanoseconds
        seconds = nanoseconds // 1_000_000_000
        remaining_ns = nanoseconds % 1_000_000_000

        # Create a timedelta object
        td = timedelta(seconds=seconds, microseconds=(remaining_ns // 1_000))

        if tz is None:
            # Create a naive datetime object
            return td
        else:
            if isinstance(tz, str):
                tz = pytz.timezone(tz)
            elif not isinstance(tz, tzinfo):
                raise ValueError("Invalid timezone provided")

            # Create an aware datetime object
            return td.replace(tzinfo=tz)
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

