def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit unsigned integer.")

    bytes = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(bytes, byteorder='big', signed=False)

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop 16 bits")
    return (self.data.pop() << 8) | self.data.pop()

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    message = {
        "DISCARD": {
            "n": n,
            "qid": qid,
            "hydration_hooks": hydration_hooks,
            "handlers": handlers
        }
    }

    self.output_queue.append(message)

def round_half_to_even(n):
    """Rounds a number to the nearest integer, rounding half to even (bankers' rounding)."""
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n >= 0:
        return int(n + 0.5) if n - int(n) == 0.5 else round(n)
    else:
        return int(n - 0.5) if n - int(n) == -0.5 else round(n)

def round_half_to_even(n):
    """Round a number to the nearest integer, rounding half to even.

    Args:
        n (float): The number to round.

    Returns:
        int: The rounded integer.
    """
    if n >= 0:
        return int(n + 0.5 - 0.5 * (n % 1 == 0.5))
    else:
        return int(n - 0.5 + 0.5 * (n % 1 == -0.5))

def round_half_to_even(n):
    """
    Round the given number to the nearest integer, rounding half to the nearest even number.

    :param n: The number to round
    :return: The rounded number
    """
    if isinstance(n, int):
        return n
    elif not isinstance(n, (float, int)):
        raise TypeError("Input must be a number")

    fractional_part = n - int(n)
    if abs(fractional_part - 0.5) < 1e-9:
        # Exactly halfway between two integers, round to nearest even
        if int(n) % 2 == 0:
            return int(n)
        else:
            return int(n) + 1
    else:
        return round(n)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to the nearest even number.

    :param n: The number to round
    :return: The rounded integer
    """
    if n % 1 == 0:
        return int(n)
    else:
        int_part = int(n)
        fractional_part = n - int_part
        if fractional_part == 0.5:
            if int_part % 2 == 0:
                return int_part
            else:
                return int_part + 1
        elif fractional_part < 0.5:
            return int_part
        else:
            return int_part + 1

def round_half_to_even(n):
    """
    Round the given number to the nearest integer, rounding halfway cases to the nearest even number.

    :param n: The number to round
    :return: The rounded number
    """
    if n % 1 == 0.5:
        return int(n) + (1 if n > 0 else -1)
    else:
        return round(n)

class PointField:
    def __init__(self, name, fields, srid_map):
        self.name = name
        self.fields = fields
        self.srid_map = srid_map

    def create_subclass(self):
        fields_str = ', '.join([f"{field['name']}: {field['type']}" for field in self.fields])
        srid_map_str = ', '.join([f"'{key}': {value}" for key, value in self.srid_map.items()])
        code = f"""class {self.name}(Point):
    __init__(self, {fields_str}, srid=None):
        super().__init__(srid={srid_map_str})
        {self._init_fields(fields)}
    """
        exec(code, globals())
        return globals()[self.name]

    def _init_fields(self, fields):
        return '\n'.join([f"self.{field['name']} = {field['name']}" for field in fields])

