def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    import sys
    from types import MethodType

    class Point:
        def __init__(self, *args, **kwargs):
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __repr__(self):
            args = ', '.join(f'{key}={value!r}' for key, value in self.__dict__.items())
            return f'{self.__class__.__name__}({args})'

    for field_name, srid in fields.items():
        if srid in srid_map:
            srid = srid_map[srid]
        else:
            raise ValueError(f'SRID {srid} not found in srid_map')

        def getter(self, field_name=field_name):
            return getattr(self, field_name)

        def setter(self, value, srid=srid):
            if srid != getattr(self, 'srid', None):
                raise ValueError(f'SRID mismatch: expected {srid}, got {getattr(self, "srid", None)}')
            setattr(self, field_name, value)

        setattr(Point, f'get_{field_name}', MethodType(getter, Point))
