def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os

    if os.name == 'nt':
        # Check for shebang and normalize if necessary
        if cmd[0].startswith('#!'):
            path = cmd[0][2:].strip()
            if os.path.isabs(path):
                cmd = (path,) + cmd[1:]
            else:
                cmd = (os.path.abspath(path),) + cmd[1:]

        # Normalize deep-path shebangs
        if os.path.isabs(cmd[0]) and os.path.exists(cmd[0]):
            cmd = (cmd[0],) + cmd[1:]

    return cmd

