            # Handle deep-path shebangs
            if len(cmd) > 1 and '/' in cmd[1]:
                interpreter = cmd[1]
                if 'python' not in interpreter:
                    # Assume the interpreter path is valid and do not change it
                    pass
                else:
                    # Extract the script path and recombine it with the interpreter
                    script_path = os.path.join(os.getcwd(), ' '.join(cmd[2:]))
                    cmd = [interpreter, script_path]

    return tuple(cmd)

