class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = {}
        self.access_times = {}
        self.access_counts = {}
        self.next_access = time.time()

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items()) if self.typed else None)
            if key in self.cache:
                self.access_times[key] = self.next_access
                self.access_counts[key] += 1
                return self.cache[key]
            else:
                result = func(*args, **kwargs)
                self.cache[key] = result
                self.access_times[key] = self.next_access
                self.access_counts[key] = 1
                if len(self.cache) > self.maxsize:
                    self.evict()
                return result
        return wrapper

    def evict(self):
        oldest_key = None
        min_time = float('inf')
        min_count = float('inf')
        for key, (time, count) in self.access_times.items():
            if time < min_time or (time == min_time and count < min_count):
                oldest_key, (min_time, min_count) = key, (time, count)
        del self.cache[oldest_key]
        del self.access_times[oldest_key]
        del self.access_counts[oldest_key]

