from functools import wraps
import threading

def cachedmethod(cache, key=None, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if key is None:
        key = hashkey

    if lock is None:
        lock = threading.Lock()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            bound_args = func.__self__ if func.__self__ else args[0]
            cache_key = key(bound_args, *args[1:], **kwargs)
            with lock:
                if cache_key not in cache:
                    cache[cache_key] = func(*args, **kwargs)
                return cache[cache_key]
        return wrapper
    return decorator

import functools
import threading

def cachedmethod(cache, key=None, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if key is None:
        key = functools.cmp_to_key(hashkey)

    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                k = key((func, args, frozenset(kwargs.items())))
                try:
                    return cache[k]
                except KeyError:
                    result = func(self, *args, **kwargs)
                    cache[k] = result
                    return result
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

