        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            if lock is None:
                lock = threading.Lock()

            with lock:
                cache_key = key(self, *args, **kwargs)
                if cache_key not in cache:
                    cache[cache_key] = func(self, *args, **kwargs)
                return cache[cache_key]
        return wrapper
    return decorator

