class StackFrame:
    def __init__(self, frame):
        self.frame = frame
        self.filename = frame.f_code.co_filename
        self.lineno = frame.f_lineno
        self.name = frame.f_code.co_name
        self.locals = frame.f_locals

class PathFrameStack:
    def __init__(self):
        self.stack = []
        self.current_level = 0

    def push(self, frame):
        if self.current_level < max_path_level:
            self.stack.append(StackFrame(frame))
            self.current_level += 1
        else:
            return False

    def pop(self):
        if self.stack:
            self.current_level -= 1
            return self.stack.pop()
        return None

def format_stack_element(frame):
    return f"{frame.filename}:{frame.lineno} in {frame.name}"

def format_stack(stack):
    return "\n".join(format_stack_element(frame) for frame in stack)

