def format_exception(e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    stack_level = 0
    path_stack = PathFrameStack()
    message = traceback.format_exception_only(e.__class__, e)[0]
    stack = traceback.extract_tb(e.__traceback__)

    for frame in reversed(stack):
        if frame.f_code.co_name != '<module>':
            stack_level += 1
            if stack_level > max_level:
                break
            if path_stack.push(frame):
                continue
            elif not path_stack.pop():
                break

    formatted_stack = format_stack(path_stack.stack)
    return f"{message.strip()}\n{formatted_stack}"

