def _legacy_mergeOrderings(orderings):
    if not orderings:
        return []

    merged = []
    processed = set()

    while orderings:
        for ordering in orderings[:]:
            if not any(x in processed for x in ordering):
                for x in ordering:
                    processed.add(x)
                    merged.append(x)
                orderings.remove(ordering)
                break
        else:
            raise ValueError("Cannot merge orderings")

    return merged

