        for b in cls.__bases__:
            if b in classes:
                inheritance[cls].append(b)

    # Function to check if a class is a direct or indirect subclass of another
    def is_subclass(child, parent):
        if child in inheritance[parent]:
            return True
        for superClass in inheritance[child]:
            if is_subclass(superClass, parent):
                return True
        return False

    # Reduce the list to minimal Bases
    minimal = []
    for cls in classes:
        if not any(is_subclass(cls, other) for other in minimal):
            minimal.append(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a set to keep track of the minimal bases
    minimal = set()

    # Iterate over each class in the input list
    for cls in classes:
        # Assume the class is minimal until proven otherwise
        is_minimal = True

        # Check if the class is a subclass of any other class in the list
        for other in classes:
            if cls is not other and issubclass(cls, other):
                # If it is, it's not minimal
                is_minimal = False
                break

        # If the class is minimal, add it to the set
        if is_minimal:
            minimal.add(cls)

    # Convert the set to a list and return the minimal bases
    return list(minimal)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Dictionary to keep track of inheritance relationships
    inheritance = {cls: cls.__bases__ for cls in classes}

    # Remove classes that are subclasses of another class in the list
    while True:
        found_reduction = False
        for cls in list(inheritance.keys()):
            # If the class is a subclass of another class in the list
            if any(base in classes for base in inheritance[cls]):
                del inheritance[cls]
                found_reduction = True
        # If no reduction was made, break the loop
        if not found_reduction:
            break

    # Sort the minimal bases based on their inheritance depth
    def sort_key(cls):
        return sum(cls in base.__bases__ for base in inheritance.values())

    return sorted(inheritance.keys(), key=sort_key)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Helper function to filter out a class if it is a subclass of another
    def is_redundant(cls, class_set):
        return any(c in class_set andissubclass(cls, c) for c in class_set)

    # Create a set to keep track of the minimal base classes
    minimal_set = set()

    # Iterate over the list of classes
    for cls in classes:
        # Check if the current class is redundant
        if not is_redundant(cls, minimal_set):
            # If not redundant, add it to the minimal set
            minimal_set.add(cls)

    # Return a sorted list of the minimal base classes
    return sorted(minimal_set, key=classes.index)

