import warnings

def to_csv(self, separator=",", header=None):
    warnings.warn("to_csv is deprecated since Lena 0.5. Use lena.output.ToCSV instead.", DeprecationWarning)

    points = self.get_points()
    if not points:
        return ""

    def point_to_string(point):
        coord_str = separator.join(str(coord) for coord in point[0])
        value_str = separator.join(str(part) for part in point[1])
        return coord_str + separator + value_str

    rows = [point_to_string(point) for point in points]
    if header is not None:
        rows.insert(0, header)

    return "\n".join(rows)

