    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    from lxml import etree

    if not isinstance(seq, etree.Element):
        return False

    def is_fill_request_element(element):
        return element.tag == 'FillRequest'

    def contains_fill_request_element(element):
        return any(is_fill_request_element(e) for e in element.iter())

    def is_not_source_sequence(element):
        return element.tag != 'Source'

    if is_fill_request_element(seq) and is_not_source_sequence(seq):
        return True

    if contains_fill_request_element(seq) and is_not_source_sequence(seq):
        return True

    return False

