def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    if not last_applied_manifest or not observer_schema or not response:
        raise ValueError("All input arguments must be non-empty lists")

    for observed_field in observer_schema:
        if observed_field not in last_applied_manifest:
            if observed_field in response:
                last_applied_manifest.append(response[observed_field])
            else:
                raise KeyError(f"Field {observed_field} not found in response")

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present

    """
    for item in observer_schema:
        if item not in last_applied_manifest:
            last_applied_manifest.append(item)

    for item in response:
        if item not in observer_schema:
            observer_schema.append(item)

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for item in observer_schema:
        if any(item == x for x in last_applied_manifest):
            continue
        if isinstance(item, dict):
            entry = {}
            for observer_field, _ in item.items():
                entry[observer_field] = find_in_response_path(response, observer_field)
            last_applied_manifest.append(entry)
        elif isinstance(item, list):
            last_applied_manifest.append(update_last_applied_manifest_list_from_resp([], item, response))
        else:
            entry = find_in_response_path(response, item)
            if entry is not None:
                last_applied_manifest.append(entry)

    return last_applied_manifest


def find_in_response_path(response, path):
    """Helper function to find a value in the response by a dotted path"""
    keys = path.split('.')
    for key in keys:
        if isinstance(response, list):
            response = next((x for x in response if str(x.get('kind', '')) == key), None)
        elif isinstance(response, dict):
            response = response.get(key, None)
        else:
            return None
    return response

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, value in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in the Kubernetes response")

        if isinstance(value, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest.get(field, {}), value, response[field]
            )
        else:
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present

    """

    for observed_field, schema_info in observer_schema.items():
        if observed_field in response:
            if isinstance(schema_info, dict) and schema_info.get('type') == 'dict':
                if observed_field not in last_applied_manifest or not last_applied_manifest[observed_field]:
                    last_applied_manifest[observed_field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[observed_field],
                    schema_info.get('properties', {}),
                    response[observed_field]
                )
            elif isinstance(schema_info, dict) and schema_info.get('type') == 'array':
                if observed_field not in last_applied_manifest or not last_applied_manifest[observed_field]:
                    last_applied_manifest[observed_field] = []
                if isinstance(response[observed_field], list):
                    for item in response[observed_field]:
                        if isinstance(item, dict):
                            last_applied_manifest[observed_field].append({})
                            update_last_applied_manifest_dict_from_resp(
                                last_applied_manifest[observed_field][-1],
                                schema_info.get('items', {}).get('properties', {}),
                                item
                            )
            else:
                if observed_field not in last_applied_manifest:
                    last_applied_manifest[observed_field] = response[observed_field]
        else:
            raise KeyError(f"Observed field '{observed_field}' not present in Kubernetes response")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}
    for resource in app.spec.manifest:
        if "custom_observer_schema" not in resource:
            resource_type = resource["resource_type"]
            resource_name = resource["resource_name"]
            default_schema = {
                "type": "object",
                "properties": {
                    "kind": {"type": "string", "enum": [resource_type]},
                    "metadata": {
                        "type": "object",
                        "properties": {
                            "name": {"type": "string"}
                        },
                        "required": ["name"],
                        "additionalProperties": False
                    },
                    "spec": {}
                },
                "required": ["kind", "metadata"],
                "additionalProperties": False
            }
            default_observer_schema[resource_name] = default_schema
    return default_observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """

    default_observer_schema = {}

    for resource in app.spec.manifest:
        resource_name = resource['apiVersion'] + '/' + resource['kind']
        if 'kubernetes_observer' in resource:
            observer_schema = resource['kubernetes_observer']
        else:
            observer_schema = {
                'apiVersion': resource['apiVersion'],
                'kind': resource['kind'],
                'metadata': {}
            }

        default_observer_schema[resource_name] = observer_schema

    return default_observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if 'observer_schema' not in resource:
            resource['observer_schema'] = {
                'kind': 'GenericObserver',
                'spec': {}
            }

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    	:class:`list`).
    """
    if isinstance(sql, bytes):
        fmt_sql = sql.decode('utf-8')
    else:
        fmt_sql = sql

    if self.SQLParams.in_style == NamedStyle:
        out_params: Dict[str, Any] = {k: None for k in params.keys()}
        for i, (k, v) in enumerate(params.items()):
            out_params[f'p{i+1}'] = v
    elif self.SQLParams.in_style == OrdinalStyle:
        out_params = [None] * len(params)
        for i, v in enumerate(params):
            out_params[i] = v
    else:
        raise ValueError("Unsupported input parameter style")

    if isinstance(sql, bytes):
        fmt_sql = fmt_sql.encode('utf-8')

    return fmt_sql, out_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    from .params import SQLParams
    params = self.SQLParams.in_style

    if isinstance(sql, str):
        s = text_type
    else:
        s = bytes_type

    if params == SQLParams.POSTGRES_NAMED:
        placeholders = iter(':p%d' % i for i in count())
        placeholder_params = {}
        formatted_sql = sql.replace('%s', next(placeholders))
    elif params == SQLParams.PLACEHOLDERS:
        placeholders = iter('?', formatmany.__next__())
        placeholder_params = {}
        formatted_sql = sql.replace('%s', next(placeholders))
    else:
        raise ValueError("Unsupported parameter style: %s" % params)

    converted_params = []
    for param_set in many_params:
        if isinstance(param_set, Mapping):
            converted_param_set = {k: v for k, v in param_set.items()}
        elif isinstance(param_set, Sequence):
            converted_param_set = [v for v in param_set]
        else:
            raise ValueError("Invalid parameter set: %s" % param_set)

        for placeholder in placeholders:
            if isinstance(converted_param_set, Mapping) and placeholder in converted_param_set:
                formatted_sql = formatted_sql.replace(placeholder, str(converted_param_set[placeholder]))
                del converted_param_set[placeholder]
            elif isinstance(converted_param_set, Sequence):
                formatted_sql = formatted_sql.replace(placeholder, str(converted_param_set.pop(0)))
            else:
                raise ValueError("Mismatched number of placeholders and parameters")

        converted_params.append(converted_param_set)

    return formatted_sql, converted_params

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    from collections.abc import Mapping, Sequence
    import re

    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(many_params, Iterable):
        raise TypeError("many_params must be an Iterable")

    formatted_sql = sql
    out_params_list = []

    for params in many_params:
        if self.SQLParams.in_style == "named":
            if not isinstance(params, Mapping):
                raise ValueError("params must be a Mapping for named parameter style")
            placeholders = {f":{key}": f"%({key})s" for key in params}
        elif self.SQLParams.in_style == "ordinal":
            if not isinstance(params, Sequence):
                raise ValueError("params must be a Sequence for ordinal parameter style")
            placeholders = {f"%({i})s": f"%({i})s" for i in range(len(params))}
        else:
            raise ValueError("Unsupported in-style parameter style")

        formatted_sql = re.sub(r"({}|{}|{})".format(*placeholders), lambda match: placeholders[match.group()], formatted_sql)

        if isinstance(params, Mapping):
            out_params_list.append(dict(params.items()))
        else:
            out_params_list.append(list(params))

    return (formatted_sql, out_params_list)

