    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if fixity is None:
        raise ValueError("Fixity block is None")
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block must contain 'files' key")
    fixity_files = fixity['files']
    if not isinstance(fixity_files, list):
        raise ValueError("'files' key in fixity block must be a list")
    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError(f"File {file} in fixity block is not in manifest")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_hash, file_info in fixity.items():
        if not isinstance(file_info, dict):
            raise ValueError("File info must be a dictionary")

        if "path" not in file_info:
            raise ValueError("File info must contain a 'path' key")

        if file_info["path"] not in manifest_files:
            raise ValueError("File path not listed in manifest: {}".format(file_info["path"]))

        if "algorithm" not in file_info:
            raise ValueError("File info must contain an 'algorithm' key")

        if "hash" not in file_info:
            raise ValueError("File info must contain a 'hash' key")

        if not isinstance(file_info["hash"], str):
            raise ValueError("File hash must be a string")

        if not isinstance(file_info["algorithm"], str):
            raise ValueError("Hash algorithm must be a string")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check that the required keys are present
    required_keys = {'digest', 'digest_type', 'filename'}
    if not required_keys.issubset(fixity):
        raise ValueError("Fixity block missing required keys")

    # Ensure filename is in manifest_files
    if fixity['filename'] not in manifest_files:
        raise ValueError("File referenced in fixity block not found in manifest")

    # Optionally, add more validation based on fixity_type and digest
    if fixity['digest_type'] != 'SHA-256':
        raise ValueError("Unsupported digest type")

    # If all checks pass
    return True

