def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """

    import zipfile
    from xml.etree import ElementTree as ET

    def parse_xml(file):
        try:
            root = ET.parse(file).getroot()
            return root
        except ET.ParseError:
            return None

    result = {}

    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        for file_info in zip_ref.infolist():
            if file_info.filename.endswith('.xml'):
                xml_data = zip_ref.read(file_info)
                xml_tree = parse_xml(xml_data)
                if xml_tree is not None:
                    basename = file_info.filename.rsplit('.', 1)[0]
                    if basename in result:
                        result[basename].append(xml_tree)
                    else:
                        result[basename] = [xml_tree]

    return result

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        import zipfile
        darij = {}
        with zipfile.ZipFile(zip_path, 'r') as z:
            for item in z.infolist():
                if item.filename.endswith('.xml'):
                    xml_data = z.open(item).read()
                    basename = item.filename.split('.')[0]
                    darij.setdefault(basename, []).append(xml_data)
        return darij
    except zipfile.BadZipFile:
        print(f"Error: The file at {zip_path} is not a valid ZIP file.")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

