def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    issue_content = issue.strip()
    number = None
    suppl = None

    if issue_content.isdigit():
        number = int(issue_content)
        suppl = 'suppl'
    elif 'suppl' in issue_content.lower():
        parts = issue_content.split()
        for part in parts:
            if part.isdigit():
                number = int(part)
            elif part.lower() == 'suppl' or part.lower() == 'spe':
                suppl = 'suppl'
            elif part.lower() == 'pr' or part == 's':
                suppl += part.lower()
        if number is None:
            for part in parts:
                if part.lower() == 'suppl' or part.lower() == 'spe':
                    suppl = 'suppl'
                    break

    return number, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    if debug:
        indent += 2

    if isinstance(self, str):
        return ' ' * indent + self

    if hasattr(self, 'toxml'):
        return self.toxml(indent=indent)

    result = ' ' * indent + '<' + self.__class__.__name__
    for attr, value in self._attrib.items():
        result += ' ' + attr + '="' + value + '"'
    result += '>\n'

    for child in self:
        result += child.pretty(indent=indent + 2, debug=debug)

    result += ' ' * indent + '</' + self.__class__.__name__ + '>\n'
    return result

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    return self.format(indent, debug)

def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        if expr[0] == '&':
            if expr[1][0] == '|':
                if expr[1][0] == expr[0][1]:
                    return expr[0][1]
            elif expr[1][0] == '&':
                if expr[1][0] == expr[0][1]:
                    return expr[0][1]
        elif expr[0] == '|':
            if expr[1][0] == '&':
                if expr[1][0] == expr[0][1]:
                    return expr[0][1]
            elif expr[1][0] == '|':
                if expr[1][0] == expr[0][1]:
                    return expr[0][1]
        return expr

    def apply_negative_absorption(expr):
        if expr[0] == '&':
            if expr[1][0] == '|':
                if expr[1][1][0] == '~':
                    if expr[1][1][1] == expr[0][1]:
                        return expr[1][2]
        elif expr[0] == '|':
            if expr[1][0] == '&':
                if expr[1][1][0] == '~':
                    if expr[1][1][1] == expr[0][1]:
                        return expr[1][2]
        return expr

    new_args = []
    for expr in args:
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        new_args.append(expr)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr.type == 'binary':
            left, op, right = expr.left, expr.op, expr.right
            if op == '&':
                if left.type == 'binary' and left.op == '|' and left.left == expr.left:
                    result.append(left.left)
                elif right.type == 'binary' and right.op == '|' and right.left == expr.left:
                    result.append(right.left)
                if left.type == 'binary' and left.op == '&' and left.right == expr.left:
                    result.append(left.right)
                elif right.type == 'binary' and right.op == '&' and right.right == expr.left:
                    result.append(right.right)
            elif op == '|':
                if left.type == 'binary' and left.op == '&' and left.left == expr.left:
                    result.append(left.left)
                elif right.type == 'binary' and right.op == '&' and right.left == expr.left:
                    result.append(right.left)
                if left.type == 'binary' and left.op == '|' and left.right == expr.left:
                    result.append(left.right)
                elif right.type == 'binary' and right.op == '|' and right.right == expr.left:
                    result.append(right.right)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        if isinstance(expr, (And, Or)):
            if isinstance(expr, And):
                if expr.left == expr.right:
                    return expr.left
                elif isinstance(expr.right, Or):
                    if expr.left == expr.right.left:
                        return expr.left
                    elif expr.left == expr.right.right:
                        return expr.left
            elif isinstance(expr, Or):
                if expr.left == expr.right:
                    return expr.left
                elif isinstance(expr.left, And):
                    if expr.right == expr.left.left:
                        return expr.right
                    elif expr.right == expr.left.right:
                        return expr.right
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, (And, Or)):
            if isinstance(expr, And):
                if isinstance(expr.right, Not):
                    if expr.left == expr.right.args[0]:
                        return expr.right.args[0]
                    elif isinstance(expr.left, And):
                        if expr.left.left == expr.right.args[0] and expr.left.right == expr.left.left:
                            return expr.left.left
            elif isinstance(expr, Or):
                if isinstance(expr.left, Not):
                    if expr.right == expr.left.args[0]:
                        return expr.right
                    elif isinstance(expr.right, Or):
                        if expr.left == expr.right.left:
                            return expr.left
                        elif expr.left == expr.right.right:
                            return expr.left
        return expr

    def process_expression(expr):
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        for arg in expr.args:
            process_expression(arg)

    results = []
    for expr in args:
        result = expr.copy()
        process_expression(result)
        results.append(result)

    return results

def absorb(self, args):
    """
