        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr.is_and():
            if expr.right.is_or():
                if expr.right.left == expr.left:
                    result.append(expr.left)
                elif expr.right.right == expr.left:
                    result.append(expr.left)
                elif expr.right.left.is_not() and expr.right.left.right == expr.left:
                    result.append(expr.right.right)
            elif expr.right.is_and():
                if expr.right.left == expr.left:
                    result.append(expr.right.right)
