import datetime

def _fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not dt.tzinfo:
        raise ValueError("The provided datetime object is not timezone-aware.")

    try:
        return dt.astimezone(self._target_tz)
    except (ValueError, OverflowError) as e:
        # Handle cases where the datetime is ambiguous or in a fold state
        if e.args[0] == "year is out of range":
            raise ValueError("The datetime object's year is out of range.")

        # Determine if the datetime is in a fold state
        if len(e.args) > 1 and e.args[1] == "No such time":
            # Convert dt to the target timezone without folding
            fold_dt = dt.replace(fold=False).astimezone(self._target_tz)
            # Check if the fold datetime is before the original datetime
            if fold_dt < dt:
                return fold_dt
            else:
                # Convert dt to the target timezone with folding
                fold_dt = dt.replace(fold=True).astimezone(self._target_tz)
                # Check if the fold datetime is after the original datetime
                if fold_dt > dt:
                    return fold_dt
                else:
                    # Raise an exception if both fold states are outside the range
                    raise ValueError("The datetime object is ambiguous and in a fold state.")
        else:
            raise e

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            original_result = namefunc(*args, **kwargs)
            return original_result.encode('utf-8')
    else:
        wrapper = namefunc

    return wrapper

