def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not style:
        raise ValueError("Style cannot be None")

    if not pieces:
        return ""

    try:
        if style == "html":
            return "<br>".join(pieces)
        elif style == "markdown":
            return "\n".join(pieces)
        elif style == "plain":
            return " ".join(pieces)
        else:
            raise ValueError("Unsupported style: {}".format(style))
    except Exception as e:
        raise RuntimeError("Failed to render pieces: {}".format(e))

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces:
        return ""

    if not isinstance(style, str):
        raise ValueError("Invalid style. Expected a string.")

    rendered_pieces = []
    for piece in pieces:
        if isinstance(piece, str):
            rendered_pieces.append(piece)
        elif hasattr(piece, 'render'):
            rendered_pieces.append(piece.render(style))
        else:
            raise ValueError(f"Invalid piece type: {type(piece)}")

    return ''.join(rendered_pieces)

