def initialize(self):
    """Create and initialize a new OCFL storage root."""

    if not isinstance(self, OCFLStorageRoot):
        raise TypeError("This method can only be called on an OCFLStorageRoot instance.")

    try:
        # Create a new directory for the OCFL storage root
        os.makedirs(self.path, exist_ok=True)

        # Initialize the inventory file with a basic structure
        inventory_path = os.path.join(self.path, 'inventory.json')
        with open(inventory_path, 'w') as f:
            inventory = {
                "version": "1.0",
                "objects": {}
            }
            json.dump(inventory, f, indent=4)

        # Initialize the layout file with a basic structure
        layout_path = os.path.join(self.path, 'layout.json')
        with open(layout_path, 'w') as f:
            layout = {
                "storage": self.path,
                "defaultOIDAlgorithm": "sha256"
            }
            json.dump(layout, f, indent=4)

        print(f"OCFL storage root initialized at {self.path}")

    except Exception as e:
        raise OCFLStorageError(f"Failed to initialize OCFL storage root: {e}") from e

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if version.startswith('v'):
            version = version[1:]
        if version.isdigit():
            version = int(version)
            return f'v{version + 1}'
        else:
            raise ValueError("Invalid version format")
    except ValueError as e:
        print(f"Error: {e}")
        return None

