def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    content_digests_record = {}

    # Load root inventory
    root_inventory_path = os.path.join(version_dirs[0], 'inventory.json')
    with open(root_inventory_path, 'r') as f:
        root_inventory = json.load(f)

    # Validate each version and record content digests
    for i, version_dir in enumerate(version_dirs):
        inventory_path = os.path.join(version_dir, 'inventory.json')
        try:
            with open(inventory_path, 'r') as f:
                inventory = json.load(f)

            # Check if inventory has all the items in the previous version
            if i > 0:
                previous_inventory = version_dirs[i-1]
                previous_inventory_path = os.path.join(previous_inventory, 'inventory.json')
                with open(previous_inventory_path, 'r') as f:
                    previous_inventory = json.load(f)

                for item in previous_inventory:
                    if item not in inventory:
                        raise MissingItemError(f"Item {item} missing in version {version_dir}")

            # Check if inventory contents are within allowed number
            if len(inventory) > MAX_INVENTORY_COUNT:
                raise ExcessiveInventoryError(f"Too many items in version {version_dir}")

            # Record content digests different from root inventory
            for item, digest in inventory.items():
                if item in root_inventory and root_inventory[item] != digest:
                    content_digests_record[item] = digest

        except FileNotFoundError:
            raise InventoryNotFoundError(f"Inventory not found for version {version_dir}")

    return content_digests_record

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    from pathlib import Path

    def is_namaste(file_path):
        try:
            with open(file_path, 'r') as file:
                for line in file:
                    if line.strip() == '0=*':
                        return True
        except (IOError, PermissionError):
            pass
        return False

    path = Path(path)

    if not path.exists():
        return "Path does not exist"

    if path.is_file():
        if is_namaste(path):
            return "inventory"
        else:
            return "file"

    if path.is_dir():
        namaste_path = path / '0=*'
        if namaste_path.exists() and is_namaste(namaste_path):
            return "root"
        else:
            return "object"

    return "Unknown path type"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not params:
        params = {}

    if not bug_ids:
        raise ValueError("Bug IDs are required to amend Bugzilla params.")

    if isinstance(bug_ids, str):
        bug_ids = [bug_ids]

    for bug_id in bug_ids:
        if not isinstance(bug_id, (int, str)):
            raise ValueError("Bug IDs must be integers or strings.")

    params['ids'] = bug_ids
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    if not isinstance(bug_ids, (list, tuple)) or not all(isinstance(x, int) for x in bug_ids):
        raise TypeError("bug_ids must be a list or tuple of integers")

    for bug_id in bug_ids:
        if str(bug_id) not in params.get('ids', {}):
            raise ValueError(f"Bug ID {bug_id} not found in params")

    for bug_id in params.get('ids', {}):
        if bug_id not in bug_ids:
            params['ids'].remove(bug_id)

    for bug_id in bug_ids:
        if bug_id not in params['ids']:
            params['ids'].append(bug_id)

    return params

