import argparse

def parse_arguments(*unparsed_arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance."""

    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Add subparsers here with their respective argument configurations
    # Example:
    # subparser = subparsers.add_parser('subcommand_name')
    # subparser.add_argument('--arg', type=str, required=True)

    namespace = parser.parse_args(unparsed_arguments)

    if namespace.subparser_name is None:
        return { "global": namespace }

    return { namespace.subparser_name: namespace }

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for name, subparser in subparsers.items():
            parsed = subparser.parse_known_args([arg])[0]
            if hasattr(parsed, 'action'):
                parsed_args[name] = parsed
                break
        else:
            remaining_args.append(arg)

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_namespaces = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        subparser_prefix = subparser_name.replace('-', '_') + '_parser'
        args_seen = []

        for action in parser._actions:
            if isinstance(action, (argparse._SubparsersAction, argparse._StoreAction)):
                args_seen.extend(action.option_strings)

        for arg in args_seen:
            if arg in unparsed_arguments:
                parsed = parser.parse_known_args(unparsed_arguments)
                parsed_namespaces[subparser_name] = parsed[0]
                remaining_arguments = parsed[1]
                break

    return parsed_namespaces, remaining_arguments

