            if action.choices:
                for choice in action.choices:
                    sub_action = subparsers.add_parser(choice)
                    for sub_action_action in sub_action._actions:
                        script += f'_autocomplete "{choice}" "borgmatic {choice}" "{_format_arg_spec(sub_action_action)}"\n'
