def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = unparsed_arguments[:]
    for name, parser in subparsers.items():
        sub_args, remaining_args = parser.parse_known_args(remaining_args)
        parsed_args[name] = sub_args
    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for subname, parser in subparsers.items():
            try:
                parsed = parser.parse_args([arg], namespace=argparse.Namespace())
                parsed_args[subname] = parsed
                remaining_args = unparsed_arguments[:unparsed_arguments.index(arg) + 1]
                break
            except SystemExit:
                pass

    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size (str): A string representing a human readable file size (e.g., '500K')

    Returns:
        int: A decimal representation of file size

    Examples:
        >>> size_to_bytes("500")
        500
        >>> size_to_bytes("1K")
        1000
    """
    if not size:
        raise ValueError("Size cannot be empty")

    size = size.strip().upper()
    mult_factors = {'K': 1000, 'M': 1000000, 'G': 1000000000}
    if size[-1] in mult_factors:
        return int(float(size[:-1]) * mult_factors[size[-1]])
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1000)
    elif size.endswith('M'):
        return int(float(size[:-1]) * 1024 * 1000)
    elif size.endswith('G'):
        return int(float(size[:-1]) * 1024 * 1024 * 1000)
    else:
        try:
            return int(size)
        except ValueError:
            raise ValueError("Invalid size format")

