    '''
    if frequency is None or frequency == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)

        if unit.startswith('week'):
            return datetime.timedelta(weeks=value)
        elif unit.startswith('day'):
            return datetime.timedelta(days=value)
        elif unit.startswith('hour'):
            return datetime.timedelta(hours=value)
        elif unit.startswith('minute'):
            return datetime.timedelta(minutes=value)
        elif unit.startswith('second'):
            return datetime.timedelta(seconds=value)
        else:
            raise ValueError(f"Unsupported unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid frequency format: {frequency}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency.lower() == "always":
        return None

    units_mapping = {
        "seconds": datetime.timedelta(seconds=1),
        "minutes": datetime.timedelta(minutes=1),
        "hours": datetime.timedelta(hours=1),
        "days": datetime.timedelta(days=1),
        "weeks": datetime.timedelta(weeks=1),
        "months": None,  # Not directly supported by timedelta, needs more logic
        "years": None    # Not directly supported by timedelta, needs more logic
    }

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    number, unit = parts
    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid number in frequency")

    unit = unit.lower()
    if unit in units_mapping:
        if unit in ('months', 'years'):
            raise ValueError(f"Unit {unit} is not directly supported by timedelta")
        return number * units_mapping[unit]
    else:
        raise ValueError(f"Unknown unit: {unit}")

