def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    for s in graph.subjects(prop):
        parents = list(graph.objects(s, prop))
        if not parents:
            roots.add(s)

    return roots

