def resolve_environment_variables(config):
    """ resolves environment variables in the configuration """
    import os
    result = {}
    for k, v in config.items():
        if isinstance(v, str) and v.startswith('${') and v.endswith('}'):
            key = v[2:-1]
            result[k] = os.getenv(key, v)
        elif isinstance(v, dict):
            result[k] = resolve_environment_variables(v)
        elif isinstance(v, list):
            result[k] = [resolve_environment_variables(item) if isinstance(item, dict) else item for item in v]
        else:
            result[k] = v
    return result

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    Arguments:
        config_filenames (list of str): A sequence of configuration filenames.
        overrides (dict, optional): A dictionary of configuration overrides.
        resolve_env (bool, optional): Whether to resolve environment variables in the configuration.

    Returns:
        tuple: A tuple containing:
            - dict: A dictionary of configuration filename to corresponding parsed configuration.
            - list of logging.LogRecord: A sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    from configparser import ConfigParser
    import logging

    config_results = {}
    log_records = []

    for filename in config_filenames:
        try:
            if filename.endswith('.json'):
                with open(filename) as f:
                    config = json.load(f)
            elif filename.endswith('.ini'):
                parser = ConfigParser()
                parser.read(filename)
                config = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                raise ValueError(f"Unsupported file format: {filename}")

            if overrides:
                config.update(overrides)

            if resolve_env:
                config = {k: os.path.expandvars(v) for k, v in config.items()}

            config_results[filename] = config

        except Exception as e:
            error_record = logging.LogRecord(level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None)
            log_records.append(error_record)

    return config_results, log_records

