                                    config_data[key] = os.environ[env_var]
                                else:
                                    log_records.append(logging.LogError(f"Environment variable {env_var} not found"))

                    config_results[config_filename] = config_data
            except json.JSONDecodeError as e:
                log_records.append(logging.LogError(f"Error decoding JSON from {config_filename}: {e}"))
            except Exception as e:
                log_records.append(logging.LogError(f"Error reading {config_filename}: {e}"))

    except Exception as e:
        log_records.append(logging.LogError(f"An unexpected error occurred: {e}"))

    return config_results, log_records

