toktype = None
tokstr  = None

def process_year(tok):
    """Process a year"""
    global year

    try:
        year = int(tok.group())
        if year < 1000 or year > 9999:
            raise ValueError
        return YEAR_TOKEN
    except ValueError:
        return -1

def process_day(tok):
    """Process a day"""
    global day

    try:
        day = int(tok.group())
        return DAY_TOKEN
    except ValueError:
        return -1

def process_time(tok):
    """Process a time"""
    global hour, minute, second, microsecond

    microsecond = 0
    tok = tok.group()
    if tok.find(':') != -1:
        tok = tok.replace(',', '.')
    hour, minute, second = map(float, tok.split(':'))
    microsecond = int((second - int(second)) * 1e6)
    return TIME_TOKEN

def process_tz(tok):
    """Process a time zone offset"""
    global tz

    tok = tok.group().replace(',', '.')
    if tok == 'Z':
        tz = tzutc
    elif tok.startswith('±'):
        offset = float(tok[1:])
        tz = tzoffset(None, int(offset * 3600))
    else:
        sign = tok[0]
        offset = int(tok[1:])
        tz = tzoffset(sign, offset)
    return TZ_TOKEN

toktypes = {
    r'([12]\d{3})': process_year,
    r'(0[1-9]|[12]\d|3[01])': process_day,
    r'([01]?[0-9]|2[0-3]):([0-5]?[0-9]):(\d{2})(?:\.(\d{6}))?': process_time,
    r'(Z|[+-]\d{2}(:?\d{2})?)': process_tz,
}

def findtoks(input_str):
    """Find all tokens in a string"""
    tokens = []
    for tok, func in toktypes.items():
        for mo in re.finditer(tok, input_str):
            if func(mo) < 0:
                raise Exception("Error processing token: " + mo.group())
            tokens.append((func(mo), mo.group(), mo.start(), mo.end()))
    return sorted(tokens, key=lambda x: x[2])

def isoparse(dt_str):
    """Parse an ISO-8601 datetime string into a datetime.datetime."""
    tokens = findtoks(dt_str)

    year_token = next((t for t in tokens if t[0] == YEAR_TOKEN), None)
    day_token = next((t for t in tokens if t[0] == DAY_TOKEN), None)
    time_token = next((t for t in tokens if t[0] == TIME_TOKEN), None)
    tz_token = next((t for t in tokens if t[0] == TZ_TOKEN), None)

    if not year_token:
        raise ValueError("No year found")

    year = year_token[1]

    if day_token:
        day = day_token[1]
    else:
        day = 1

    if time_token:
        hour, minute, second, microsecond = time_token[1], time_token[2], time_token[3], time_token[4]
    else:
        hour, minute, second, microsecond = 0, 0, 0, 0

    if tz_token:
        tz = tz_token[1]
    else:
        tz = tzutc

    dt = datetime(int(year), int(day), hour, minute, second, microsecond, tzinfo=tz)
    return dt

