from typing import Callable, Set, Tuple

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    original_text = text
    replaced_text = list(text)

    i = 0
    while i < len(text):
        if text[i:i+3] == '<code>':
            in_code_block = True
            i += 5
        elif text[i:i+6] == '</code>':
            in_code_block = False
            i += 7
        elif not in_code_block and text[i:i+3] == '<tag>':
            tag_start = i + 3
            tag_end = text.find('</tag>', tag_start)
            if tag_end != -1:
                tag_word = text[tag_start:tag_end]
                tags.add(tag_word)
                i = tag_end + 5
                if replacer:
                    replacement = replacer(tag_word)
                    if replacement:
                        replaced_text[tag_start:tag_end] = replacement
            else:
                break
        else:
            i += 1

    return tags, ''.join(replaced_text)

