@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, (list, tuple)):
            for sub_var in var:
                if isinstance(sub_var, dict):
                    vars_dict.update(sub_var)
                else:
                    raise ValueError("Each element in extra_vars list must be a dictionary or a list of dictionaries")
        else:
            raise ValueError("Each element in extra_vars list must be a dictionary or a list of dictionaries")

    return vars_dict

