def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flatten_dict = {}

    # Check if the plugin directory exists
    if not os.path.isdir(plugin_dir):
        return flatten_dict

    # Walk through the directory
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)

                # Load the JSON file
                with open(file_path, 'r') as f:
                    plugin_spec = json.load(f)

                    # Flatten the dictionary
                    flatten_dict.update(_flatten_dict(plugin_spec, file_path))

    return flatten_dict

def _flatten_dict(d, parent_key=''):
    items = {}
    for k, v in d.items():
        new_key = f"{parent_key}.{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(_flatten_dict(v, new_key))
        elif isinstance(v, list):
            for i, item in enumerate(v):
                items.update(_flatten_dict({f"{new_key}[{i}]": item}, new_key))
        else:
            items[new_key] = v
    return items

